import{_ as s,o as a,c as n,a5 as t}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"83. Inline Assembly and Hardware Access","description":"The Little Book of C — 83. Inline Assembly and Hardware Access","frontmatter":{"title":"83. Inline Assembly and Hardware Access","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Portable and Modern C"],"description":"The Little Book of C — 83. Inline Assembly and Hardware Access","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":83,"sidebarWeight":83,"lang":"en-US","alternateEn":"/posts/c教程/en-US/09-Portable and Modern C/083-Inline Assembly and Hardware Access","alternateZh":"/posts/c教程/zh-CN/09-可移植与现代 C/083-Inline Assembly and Hardware Access"},"headers":[],"relativePath":"posts/c教程/en-US/09-Portable and Modern C/083-Inline Assembly and Hardware Access.md","filePath":"posts/c教程/en-US/09-Portable and Modern C/083-Inline Assembly and Hardware Access.md","lastUpdated":1790163617000}'),o={name:"posts/c教程/en-US/09-Portable and Modern C/083-Inline Assembly and Hardware Access.md"};function i(l,e,p,d,r,c){return a(),n("div",null,[...e[0]||(e[0]=[t(`<p>[中文版本](/posts/c教程/zh-CN/09-可移植与现代 C/083-Inline Assembly and Hardware Access)</p><p>C gives you precise control over memory and performance, but sometimes you need to go one level deeper, directly to the CPU. That’s where inline assembly comes in: embedding assembly language inside your C code to optimize performance or access hardware-level features.</p><p>This chapter will show how to mix C and assembly safely, portably, and meaningfully.</p><h4 id="step-1-what-is-inline-assembly" tabindex="-1">Step 1. What Is Inline Assembly? <a class="header-anchor" href="#step-1-what-is-inline-assembly" aria-label="Permalink to &quot;Step 1. What Is Inline Assembly?&quot;">​</a></h4><p>Inline assembly lets you insert small snippets of machine instructions into your C program. You can use it to:</p><ul><li>Access CPU instructions not exposed by C.</li><li>Optimize performance-critical paths.</li><li>Implement hardware drivers or low-level routines.</li></ul><p>However, it’s also non-portable and compiler-specific, so use it sparingly and isolate it behind clean C interfaces.</p><h4 id="step-2-two-common-flavors" tabindex="-1">Step 2. Two Common Flavors <a class="header-anchor" href="#step-2-two-common-flavors" aria-label="Permalink to &quot;Step 2. Two Common Flavors&quot;">​</a></h4><p>GCC / Clang syntax (AT&amp;T or Intel style) Uses the<code>asm</code> or<code>__asm__</code> keyword.</p><p>MSVC syntax Uses<code>__asm { ... }</code> inside functions.</p><p>We’ll focus on GCC/Clang syntax, since it’s used in most systems programming contexts.</p><h4 id="step-3-basic-inline-assembly-example" tabindex="-1">Step 3. Basic Inline Assembly Example <a class="header-anchor" href="#step-3-basic-inline-assembly-example" aria-label="Permalink to &quot;Step 3. Basic Inline Assembly Example&quot;">​</a></h4><p>Tiny Code: Print CPU ID register (x86 only)</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    unsigned int eax, ebx, ecx, edx;</span></span>
<span class="line"><span>    eax = 0;</span></span>
<span class="line"><span>    __asm__ __volatile__(</span></span>
<span class="line"><span>        &quot;cpuid&quot;</span></span>
<span class="line"><span>        : &quot;=a&quot;(eax), &quot;=b&quot;(ebx), &quot;=c&quot;(ecx), &quot;=d&quot;(edx)</span></span>
<span class="line"><span>        : &quot;a&quot;(0)</span></span>
<span class="line"><span>    );</span></span>
<span class="line"><span>    printf(&quot;CPU Vendor: %.4s%.4s%.4s\\n&quot;,</span></span>
<span class="line"><span>           (char*)&amp;ebx, (char*)&amp;edx, (char*)&amp;ecx);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Explanation:</p><ul><li><code>cpuid</code> is a CPU instruction that fills registers with information.</li><li><code>&quot;=a&quot;(eax)</code> means “store the output of register<code>eax</code> into variable<code>eax</code>.”</li><li><code>: &quot;a&quot;(0)</code> means “put 0 into<code>eax</code> before running the instruction.”</li><li>The<code>__volatile__</code> keyword tells the compiler not to optimize it away.</li></ul><h4 id="step-4-gcc-inline-assembly-syntax" tabindex="-1">Step 4. GCC Inline Assembly Syntax <a class="header-anchor" href="#step-4-gcc-inline-assembly-syntax" aria-label="Permalink to &quot;Step 4. GCC Inline Assembly Syntax&quot;">​</a></h4><p>General form:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>asm volatile (&quot;instruction list&quot;</span></span>
<span class="line"><span>              : output_operands</span></span>
<span class="line"><span>              : input_operands</span></span>
<span class="line"><span>              : clobbered_registers);</span></span></code></pre></div><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>asm volatile (&quot;addl %%ebx, %%eax&quot;</span></span>
<span class="line"><span>              : &quot;=a&quot;(result)</span></span>
<span class="line"><span>              : &quot;a&quot;(x), &quot;b&quot;(y));</span></span></code></pre></div><p>Explanation:</p><ul><li><code>&quot;addl %%ebx, %%eax&quot;</code>, assembly instruction</li><li><code>&quot;=a&quot;(result)</code>, output in<code>eax</code> goes to<code>result</code></li><li><code>&quot;a&quot;(x), &quot;b&quot;(y)</code>, inputs: put<code>x</code> in<code>eax</code>,<code>y</code> in<code>ebx</code></li></ul><h4 id="step-5-reading-cpu-cycle-counters" tabindex="-1">Step 5. Reading CPU Cycle Counters <a class="header-anchor" href="#step-5-reading-cpu-cycle-counters" aria-label="Permalink to &quot;Step 5. Reading CPU Cycle Counters&quot;">​</a></h4><p>Tiny Code: Measure CPU cycles between operations</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>unsigned long long rdtsc(void) {</span></span>
<span class="line"><span>    unsigned int lo, hi;</span></span>
<span class="line"><span>    __asm__ __volatile__(&quot;rdtsc&quot; : &quot;=a&quot;(lo), &quot;=d&quot;(hi));</span></span>
<span class="line"><span>    return ((unsigned long long)hi &lt;&lt; 32) | lo;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    unsigned long long start = rdtsc();</span></span>
<span class="line"><span>    for (volatile int i = 0; i &lt; 1000000; i++);</span></span>
<span class="line"><span>    unsigned long long end = rdtsc();</span></span>
<span class="line"><span>    printf(&quot;Cycles: %llu\\n&quot;, end - start);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Explanation:</p><ul><li><code>rdtsc</code> reads the CPU’s timestamp counter.</li><li>It’s a precise measure of time in CPU cycles, great for microbenchmarking.</li></ul><h4 id="step-6-writing-to-i-o-ports-embedded-or-kernel-context" tabindex="-1">Step 6. Writing to I/O Ports (Embedded or Kernel Context) <a class="header-anchor" href="#step-6-writing-to-i-o-ports-embedded-or-kernel-context" aria-label="Permalink to &quot;Step 6. Writing to I/O Ports (Embedded or Kernel Context)&quot;">​</a></h4><p>If you’re writing embedded code or OS kernels, you often interact with hardware registers directly.</p><p>Example (x86, privileged mode only):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>static inline void outb(unsigned short port, unsigned char value) {</span></span>
<span class="line"><span>    __asm__ __volatile__(&quot;outb %0, %1&quot; : : &quot;a&quot;(value), &quot;Nd&quot;(port));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>This writes a byte to an I/O port, used for devices like serial ports, timers, or PIC controllers.</p><p>In user-space, you generally can’t do this (needs kernel privileges).</p><h4 id="step-7-memory-barriers-and-cpu-fences" tabindex="-1">Step 7. Memory Barriers and CPU Fences <a class="header-anchor" href="#step-7-memory-barriers-and-cpu-fences" aria-label="Permalink to &quot;Step 7. Memory Barriers and CPU Fences&quot;">​</a></h4><p>When working with concurrency or hardware, you may need to control instruction ordering.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__asm__ __volatile__(&quot;mfence&quot; ::: &quot;memory&quot;);</span></span></code></pre></div><p>This tells the CPU and compiler not to reorder memory operations, essential for writing thread-safe or device-control code at the hardware level.</p><h4 id="step-8-register-constraints" tabindex="-1">Step 8. Register Constraints <a class="header-anchor" href="#step-8-register-constraints" aria-label="Permalink to &quot;Step 8. Register Constraints&quot;">​</a></h4><p>GCC lets you specify which registers to use.</p><table tabindex="0"><thead><tr><th>Constraint</th><th>Register</th><th>Meaning</th></tr></thead><tbody><tr><td><code>&quot;a&quot;</code></td><td><code>eax</code></td><td>accumulator</td></tr><tr><td><code>&quot;b&quot;</code></td><td><code>ebx</code></td><td>base</td></tr><tr><td><code>&quot;c&quot;</code></td><td><code>ecx</code></td><td>counter</td></tr><tr><td><code>&quot;d&quot;</code></td><td><code>edx</code></td><td>data</td></tr><tr><td><code>&quot;S&quot;</code></td><td><code>esi</code></td><td>source index</td></tr><tr><td><code>&quot;D&quot;</code></td><td><code>edi</code></td><td>destination index</td></tr></tbody></table><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>asm(&quot;mul %1&quot; : &quot;=a&quot;(res) : &quot;r&quot;(x));</span></span></code></pre></div><p>The<code>&quot;r&quot;</code> constraint lets the compiler choose any register.</p><h4 id="step-9-mixing-assembly-and-c-functions" tabindex="-1">Step 9. Mixing Assembly and C Functions <a class="header-anchor" href="#step-9-mixing-assembly-and-c-functions" aria-label="Permalink to &quot;Step 9. Mixing Assembly and C Functions&quot;">​</a></h4><p>You can write small routines in separate<code>.S</code> files (pure assembly) and call them from C:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># file: add.S</span></span>
<span class="line"><span>.global add_two</span></span>
<span class="line"><span>add_two:</span></span>
<span class="line"><span>    addl %esi, %edi</span></span>
<span class="line"><span>    movl %edi, %eax</span></span>
<span class="line"><span>    ret</span></span></code></pre></div><p>Then in C:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int add_two(int a, int b);</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, add_two(5, 7));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>This hybrid style is used in OS kernels, bootloaders, and math libraries.</p><h4 id="step-10-tiny-code-inline-assembly-add-function" tabindex="-1">Step 10. Tiny Code: Inline Assembly Add Function <a class="header-anchor" href="#step-10-tiny-code-inline-assembly-add-function" aria-label="Permalink to &quot;Step 10. Tiny Code: Inline Assembly Add Function&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int add_fast(int a, int b) {</span></span>
<span class="line"><span>    int result;</span></span>
<span class="line"><span>    __asm__ (&quot;addl %1, %0&quot; : &quot;=r&quot;(result) : &quot;r&quot;(b), &quot;0&quot;(a));</span></span>
<span class="line"><span>    return result;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, add_fast(3, 5));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>The<code>&quot;0&quot;(a)</code> constraint tells the compiler to use the same register for input and output.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Inline assembly teaches you what really happens beneath your C code. Even if you rarely use it, understanding it helps you:</p><ul><li>Read compiler-generated assembly (<code>gcc -S</code>)</li><li>Optimize performance-critical code</li><li>Understand how system calls, context switches, and kernel traps work</li></ul><p>It’s where software meets hardware, the true metal of computing.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Write a small inline assembly snippet that swaps two integers.</li><li>Print the CPU vendor string with<code>cpuid</code>.</li><li>Use<code>rdtsc()</code> to benchmark your function.</li><li>Inspect compiler-generated assembly using<code>gcc -S</code>.</li><li>Try to reimplement a basic math operation in assembly and compare performance.</li></ol><p>Next, you’ll learn cross-compilation, how to build your C programs for other architectures and systems, from your own machine.</p>`,60)])])}const m=s(o,[["render",i]]);export{h as __pageData,m as default};
